package org.dextur.reputation.paper;

import java.util.*;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.application.*;

/** One bounded main-thread refresh task; all storage reads use PolicyApplication workers. */
final class PolicyEffects implements Listener,AutoCloseable {
    static final NamespacedKey HEALTH_KEY=new NamespacedKey("dexturreputation","reputation-health");
    record Layout(boolean enabled,int entry,int size,Material material){static Layout load(java.nio.file.Path directory)throws Exception{var y=TierConfiguration.map(TierConfiguration.configuration(directory,"gui.yml").get("policy-panel"));int size=YamlFiles.number(y,"size",27,54);Material material=Material.matchMaterial(YamlFiles.text(y,"material"));if(size%9!=0||material==null||!material.isItem()||material.isAir())throw new IllegalArgumentException("Policy panel layout");return new Layout(YamlFiles.flag(y,"enabled"),YamlFiles.number(y,"entry-slot",0,53),size,material);}}
    static final class Panel implements InventoryHolder{final UUID owner;Inventory inventory;boolean busy;Panel(UUID owner){this.owner=owner;}public Inventory getInventory(){return inventory;}}
    private final DexturReputationPlugin plugin;private final PolicyApplication policies;private final PolicyCommands commands;private final Messages messages;private final Layout layout;private final java.util.concurrent.ConcurrentHashMap<UUID,Applied> applied=new java.util.concurrent.ConcurrentHashMap<>();
    private VotingGui voting;void voting(VotingGui voting){this.voting=voting;}
    record Applied(ReputationPolicyResult.Revision revision,String amount){}
    Optional<String> modifier(UUID player,ReputationPolicyResult.Revision revision){var value=applied.get(player);return value!=null&&value.revision().equals(revision)?Optional.of(value.amount()):Optional.empty();}
    private void reconcile(Player player,ReputationPolicyResult result){health(player,result,policies.configuration().healthEnabled());var attribute=player.getAttribute(Attribute.MAX_HEALTH);double amount=attribute==null?0:attribute.getModifiers().stream().filter(m->m.getKey().equals(HEALTH_KEY)).mapToDouble(AttributeModifier::getAmount).sum();if(applied.size()<4096||applied.containsKey(player.getUniqueId()))applied.put(player.getUniqueId(),new Applied(result.revision(),java.math.BigDecimal.valueOf(amount).setScale(6,java.math.RoundingMode.HALF_EVEN).stripTrailingZeros().toPlainString()));}
    private final Set<UUID> pending=new HashSet<>();private int cursor;private boolean closed;
    PolicyEffects(DexturReputationPlugin plugin,PolicyApplication policies,PolicyCommands commands,Messages messages,Layout layout){this.plugin=plugin;this.policies=policies;this.commands=commands;this.messages=messages;this.layout=layout;}
    void refresh(){cursor=0;}
    void tick(){if(closed||!plugin.ready())return;var online=plugin.getServer().getOnlinePlayers().stream().sorted(Comparator.comparing(Player::getUniqueId)).toList();for(int i=0;i<Math.min(16,online.size());i++){var player=online.get(Math.floorMod(cursor++,online.size()));var cached=policies.cached(player.getUniqueId(),"health.maximum");if(cached.isPresent())reconcile(player,cached.get());else request(player);}}
    void request(Player player){if(closed||pending.size()>=4096||!pending.add(player.getUniqueId()))return;policies.evaluate(player.getUniqueId(),"health.maximum").whenComplete((result,error)->plugin.onMain(()->{pending.remove(player.getUniqueId());if(closed||!player.isOnline())return;if(error!=null){plugin.logFailure("health policy",error);return;}var current=policies.cached(player.getUniqueId(),"health.maximum");if(current.isPresent()&&current.get().revision().equals(result.revision()))reconcile(player,result);}));}
    static double projected(AttributeInstance attribute,double owned){double add=owned,scalar=0,multiply=1;for(var modifier:attribute.getModifiers()){if(modifier.getKey().equals(HEALTH_KEY))continue;switch(modifier.getOperation()){case ADD_NUMBER->add+=modifier.getAmount();case ADD_SCALAR->scalar+=modifier.getAmount();case MULTIPLY_SCALAR_1->multiply*=1+modifier.getAmount();}}return (attribute.getBaseValue()+add)*(1+scalar)*multiply;}
    static void health(Player player,ReputationPolicyResult policy,boolean enabled){health(player,player.getAttribute(Attribute.MAX_HEALTH),policy,enabled);}
    static void health(Player player,AttributeInstance attribute,ReputationPolicyResult policy,boolean enabled){if(attribute==null)return;double delta=enabled&&policy.permitted()&&policy.value()!=null?policy.value().doubleValue()-20.0:0;double projected=projected(attribute,delta);if(!Double.isFinite(projected)||projected<2)delta=0;var existing=attribute.getModifiers().stream().filter(m->m.getKey().equals(HEALTH_KEY)).toList();if(existing.size()==1&&Double.compare(existing.getFirst().getAmount(),delta)==0||existing.isEmpty()&&delta==0)return;double target=Math.min(attribute.getValue(),Math.max(1,projected(attribute,delta)));if(player.getHealth()>target)player.setHealth(target);for(var modifier:existing)attribute.removeModifier(modifier);if(delta!=0)attribute.addTransientModifier(new AttributeModifier(HEALTH_KEY,delta,AttributeModifier.Operation.ADD_NUMBER));double maximum=attribute.getValue();if(maximum>=1&&player.getHealth()>maximum)player.setHealth(maximum);}
    static void remove(Player player){remove(player,player.getAttribute(Attribute.MAX_HEALTH));}
    static void remove(Player player,AttributeInstance attribute){if(attribute==null)return;for(var modifier:List.copyOf(attribute.getModifiers()))if(modifier.getKey().equals(HEALTH_KEY))attribute.removeModifier(modifier);if(attribute.getValue()>=1&&player.getHealth()>attribute.getValue())player.setHealth(attribute.getValue());}
    void attach(Player player,VotingGui.Session session){if(!layout.enabled()||!policies.configuration().informationEnabled()||!player.hasPermission("dexturreputation.policies")||!player.hasPermission("dexturreputation.use")||!player.getUniqueId().equals(session.target)||(session.inventory.getSize()!=27&&layout.entry()>=session.inventory.getSize())||session.inventory.getItem(session.inventory.getSize()==27?22:layout.entry())!=null)return;var item=new ItemStack(layout.material());var meta=item.getItemMeta();meta.displayName(messages.content(commands.language(player),"policy-title",Map.of()));item.setItemMeta(meta);session.inventory.setItem(session.inventory.getSize()==27?22:layout.entry(),item);session.actions.put(session.inventory.getSize()==27?22:layout.entry(),()->open(player));}
    void open(Player player){if(!layout.enabled()||!policies.configuration().informationEnabled()){commands.send(player,"policy-information-disabled",Map.of());return;}if(!player.hasPermission("dexturreputation.policies")||!player.hasPermission("dexturreputation.use")){commands.send(player,"no-permission",Map.of());return;}var panel=new Panel(player.getUniqueId());panel.inventory=Bukkit.createInventory(panel,27,messages.content(commands.language(player),"policy-title",Map.of()));player.openInventory(panel.inventory);policies.evaluate(player.getUniqueId(),"reputation.vote").whenComplete((result,error)->plugin.onMain(()->{if(closed||!player.isOnline()||player.getOpenInventory().getTopInventory().getHolder()!=panel)return;if(error!=null){commands.send(player,"unavailable",Map.of());player.closeInventory();return;}if(!player.hasPermission("dexturreputation.policies")||!player.hasPermission("dexturreputation.use")){commands.send(player,"no-permission",Map.of());player.closeInventory();return;}int index=0;for(String id:org.dextur.reputation.domain.policy.PolicyRules.BUILT_INS){var cached=policies.cached(player.getUniqueId(),id);if(cached.isEmpty())continue;var item=new ItemStack(layout.material());var meta=item.getItemMeta();meta.displayName(net.kyori.adventure.text.minimessage.MiniMessage.miniMessage().deserialize(policies.policies().get(id).names().getOrDefault(commands.language(player).name(),id)));meta.lore(List.of(messages.content(commands.language(player),"policy-summary",commands.publicValues(cached.get(),player))));item.setItemMeta(meta);panel.inventory.setItem(index++,item);}var close=new ItemStack(Material.OAK_DOOR);var meta=close.getItemMeta();meta.displayName(messages.content(commands.language(player),"gui-close",Map.of()));close.setItemMeta(meta);panel.inventory.setItem(MenuGeometry.close(panel.inventory.getSize()),close);var back=new ItemStack(Material.ARROW);var backMeta=back.getItemMeta();backMeta.displayName(messages.content(commands.language(player),"gui-back",Map.of()));back.setItemMeta(backMeta);panel.inventory.setItem(MenuGeometry.back(panel.inventory.getSize()),back);}));}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof Panel panel))return;event.setCancelled(true);
        if(!(event.getWhoClicked() instanceof Player player)||!player.getUniqueId().equals(panel.owner)||panel.busy||closed||!plugin.ready()||event.getClick()!=ClickType.LEFT||!player.hasPermission("dexturreputation.use")||!player.hasPermission("dexturreputation.policies"))return;
        int slot=event.getRawSlot();if(slot!=MenuGeometry.close(panel.inventory.getSize())&&slot!=MenuGeometry.back(panel.inventory.getSize()))return;panel.busy=true;
        plugin.getServer().getScheduler().runTask(plugin,()->{if(!player.isOnline()||player.getOpenInventory().getTopInventory().getHolder()!=panel)return;if(slot==MenuGeometry.back(panel.inventory.getSize())&&voting!=null)voting.open(player,player.getUniqueId(),player.getName());else player.closeInventory();});
    }
    void closePanels(){for(var player:plugin.getServer().getOnlinePlayers())if(player.getOpenInventory().getTopInventory().getHolder() instanceof Panel)player.closeInventory();}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=false)public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof Panel)event.setCancelled(true);}
    void quit(Player player){applied.remove(player.getUniqueId());pending.remove(player.getUniqueId());remove(player);}
    @Override public void close(){closed=true;applied.clear();pending.clear();for(var player:plugin.getServer().getOnlinePlayers()){remove(player);if(player.getOpenInventory().getTopInventory().getHolder() instanceof Panel)player.closeInventory();}}
}
